import copy
import json
from pathlib import Path

# Original configuration values, used to check that unrelated values survive.
ORIGINAL = {'services/service-01.json': {'service': 'notify-01', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 3, 'max_workers_backup': 9, 'queue_depth': 17}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-1']}, 'services/service-02.json': {'service': 'notify-02', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 4, 'max_workers_backup': 10, 'queue_depth': 34}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-2']}, 'services/service-03.json': {'service': 'notify-03', 'deployment': {'region': 'us-east', 'enabled': True}, 'limits': {'max_workers': 5, 'max_workers_backup': 11, 'queue_depth': 51}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-0']}, 'services/service-04.json': {'service': 'notify-04', 'deployment': {'region': 'eu-west', 'enabled': False}, 'limits': {'max_workers': 6, 'max_workers_backup': 12, 'queue_depth': 68}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-1']}, 'services/service-05.json': {'service': 'notify-05', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 7, 'max_workers_backup': 13, 'queue_depth': 85}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-2']}, 'services/service-06.json': {'service': 'notify-06', 'deployment': {'region': 'us-east', 'enabled': True}, 'limits': {'max_workers': 8, 'max_workers_backup': 14, 'queue_depth': 102}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-0']}, 'services/service-07.json': {'service': 'notify-07', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 9, 'max_workers_backup': 15, 'queue_depth': 119}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-1']}, 'services/service-08.json': {'service': 'notify-08', 'deployment': {'region': 'eu-west', 'enabled': False}, 'limits': {'max_workers': 10, 'max_workers_backup': 16, 'queue_depth': 136}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-2']}, 'services/service-09.json': {'service': 'notify-09', 'deployment': {'region': 'us-east', 'enabled': True}, 'limits': {'max_workers': 11, 'max_workers_backup': 17, 'queue_depth': 153}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-0']}, 'services/service-10.json': {'service': 'notify-10', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 12, 'max_workers_backup': 18, 'queue_depth': 170}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-1']}, 'services/service-11.json': {'service': 'notify-11', 'deployment': {'region': 'eu-west', 'enabled': True}, 'limits': {'max_workers': 13, 'max_workers_backup': 19, 'queue_depth': 187}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-2']}, 'services/service-12.json': {'service': 'notify-12', 'deployment': {'region': 'us-east', 'enabled': False}, 'limits': {'max_workers': 14, 'max_workers_backup': 20, 'queue_depth': 204}, 'max_workers': 99, 'labels': ['customer-mail', 'pool-0']}}
expected = copy.deepcopy(ORIGINAL)
for obj in expected.values():
    if obj['deployment']['region'] == 'eu-west' and obj['deployment']['enabled'] is True:
        obj['limits']['max_workers'] = 12
actual = {str(p) for p in Path('services').glob('*.json') if p.is_file()}
assert actual == set(expected), (actual, set(expected))
for name, obj in expected.items():
    actual_obj = json.loads(Path(name).read_text(encoding='utf-8'))
    assert actual_obj == obj, name
    assert actual_obj['deployment']['enabled'] is obj['deployment']['enabled'], name
    if obj['deployment']['region'] == 'eu-west' and obj['deployment']['enabled'] is True:
        assert type(actual_obj['limits']['max_workers']) is int, name
print('configuration values match')
